{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.wtw_d2p as WITH formatted_data AS ( SELECT \"Product Title\" AS product_title, TRIM(\"Shopify Product ID\")::VARCHAR AS shopify_product_id, COALESCE( TRY_TO_DATE(\"Request Date\", \'YYYY-MM-DD\'), TRY_TO_DATE(\"Request Date\", \'DD/MM/YY\') ) AS request_date, TRY_TO_DECIMAL(\"Request Count\") AS req_count, SUM(TRY_TO_DECIMAL(\"Request Count\")) OVER ( PARTITION BY TRIM(\"Shopify Product ID\") ORDER BY COALESCE( TRY_TO_DATE(\"Request Date\", \'YYYY-MM-DD\'), TRY_TO_DATE(\"Request Date\", \'DD/MM/YY\') ) ) AS cumulative_wishlist_count, RANK() OVER ( PARTITION BY TRIM(\"Shopify Product ID\") ORDER BY COALESCE( TRY_TO_DATE(\"Request Date\", \'YYYY-MM-DD\'), TRY_TO_DATE(\"Request Date\", \'DD/MM/YY\') ) ASC ) AS cumulative_wishlist_day_count FROM snitch_db.maplemonk.design_wtw_wishlist WHERE \"Request Date\" != \'Request Date\' ), pre_wishlist_rate AS ( SELECT shopify_product_id, product_title, MIN(request_date) AS created_date, SUM(req_count::int) AS total_wishlists_1stweek, (SUM(req_count::int) / COUNT(CUMULATIVE_WISHLIST_DAY_COUNT))::int AS wishlist_rate FROM formatted_data WHERE cumulative_wishlist_day_count <=7 GROUP BY shopify_product_id,product_title ORDER BY shopify_product_id, created_date ), sku_media AS ( SELECT id, SUBSTRING(id, CHARINDEX(\'/Product/\', id) + LEN(\'/Product/\'), LEN(id))::varchar AS shopify_product_id, producttype as category, LEFT(m.value:sku::STRING, LENGTH(m.value:sku::STRING) - POSITION(\'-\' IN REVERSE(m.value:sku::STRING))) AS sku_group FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(INPUT => t.media) AS f, LATERAL FLATTEN(INPUT => t.variants) AS m qualify row_number() over (partition by id order by category desc) =1 ), image_url as ( SELECT --Changes made here SUBSTRING(id, CHARINDEX(\'/Product/\', id) + LEN(\'/Product/\'), LEN(id))::varchar AS shopify_product_id, LEFT(variant.value:sku::STRING, LENGTH(variant.value:sku::STRING) - POSITION(\'-\' IN REVERSE(variant.value:sku::STRING))) AS sku_group, image.value:\"preview\":\"image\":\"url\"::string AS image_url FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(input => parse_json(t.media)) AS image, LATERAL FLATTEN(input => PARSE_JSON(t.variants)) AS variant, WHERE image.value:\"mediaContentType\"::string = \'IMAGE\' qualify ROW_NUMBER() OVER (PARTITION BY t.id ORDER BY image.index) = 1 ), wishlist_rate as ( select a.*, category, c.image_url, b.sku_group from pre_wishlist_rate a left join sku_media b on a.shopify_product_id = b.shopify_product_id left join image_url c on b.shopify_product_id = c.shopify_product_id --changes made here ), overall_percentiles AS ( SELECT (PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY wishlist_rate))::int AS p50_overall, (PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY wishlist_rate))::int AS p75_overall, (PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY wishlist_rate))::int AS p90_overall FROM wishlist_rate ), category_percentile as ( SELECT category, (PERCENTILE_CONT(0.5) WITHIN GROUP (ORDER BY wishlist_rate))::int AS p50, (PERCENTILE_CONT(0.75) WITHIN GROUP (ORDER BY wishlist_rate))::int AS p75, (PERCENTILE_CONT(0.9) WITHIN GROUP (ORDER BY wishlist_rate))::int AS p90 FROM wishlist_rate group by 1 ), main_data as ( select a.*, p50_overall, p75_overall, p90_overall, p50, p75, p90 from wishlist_rate a join overall_percentiles b left join category_percentile c on a.category = c.category qualify row_number() over (partition by shopify_product_id order by image_url desc) =1 ), final_styles as ( select *, case when wishlist_rate >= p90 and wishlist_rate >=p90_overall then \'high\' when wishlist_rate >= p75 and wishlist_rate < p90 and wishlist_rate >=p75_overall and wishlist_rate <p90_overall then \'medium\' when wishlist_rate >= p50 and wishlist_rate < p75 and wishlist_rate >=p50_overall and wishlist_rate <p75_overall then \'low\' when wishlist_rate >= 20 then \'medium\' else \'no\' end as confidence from main_data ), moq_pre as ( select a.sku_group, b.category, a.inventory_on_inward_date from snitch_db.maplemonk.original_ros_str_eoq a left join snitch_db.maplemonk.metafields_data b on a.sku_group = b.sku_group ), moq as ( select category, div0(sum(inventory_on_inward_date),count(category))::int as moq from moq_pre where category is not null group by 1 ) select a.*, case when confidence = \'no\' then 0 when confidence = \'high\' then moq*2 when confidence = \'medium\' then moq*1.5 when confidence = \'low\' then moq else 0 end as quant_req, b.moq from final_styles a left join moq b on a.category = b.category;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

